// lib/motion-lesson/samples.ts — EDU-05 motion lessons, phase B (2026-11-10): the PREVIEW's lessons.
//
// Until a teacher can record (the recorder waits for the owner's privacy line and the teacher agreement's consent
// clause), the player has something real to play: the owner's OWN takes, already committed as camera frames
// (lib/pose/__fixtures__, "owner's own DeepMotion capture"), run through the runtime adapter and packed as lesson files.
// The files ride here as base64 (samples.data.ts, GENERATED by scripts/motion-lesson/build-samples.mts; 1–2 KB each), so
// the page fetches nothing and the browser opens them with the same decodeLesson a stored lesson will use.
//
// samples.test.ts holds the data to the fixtures: each file decodes, passes lessonErrors, and is the lesson the adapter
// builds from its take today (a change to the adapter means: run the generator again).
//
// Client-safe. The takes and the adapter are NOT imported here (sampleSpecs.ts, the generator's and the test's side).
import { decodeLesson, type MotionLesson } from './format';
import { SAMPLE_DATA } from './samples.data';

export interface SampleLesson {
  id: string;
  /** The lesson's title (in its file too). */
  title: string;
  /** The picker's chip: two words at most. */
  chip: string;
}

export const SAMPLE_LESSONS: readonly SampleLesson[] = [
  { id: 'low-jumps', title: 'Four low jumps', chip: 'Low jumps' },
  { id: 'max-jump', title: 'Low, max, low', chip: 'Max jump' },
  { id: 'two-foot', title: 'Two-foot take-off', chip: 'Two-foot' },
  { id: 'one-foot', title: 'One-foot take-off', chip: 'One-foot' },
];

/** base64 → bytes, in a browser and in node. */
export function bytesOf(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** A sample's lesson, decoded from its file; null for an id that is not a sample or a file that does not open. */
export async function loadSample(id: string): Promise<MotionLesson | null> {
  const b64 = SAMPLE_DATA[id];
  return b64 ? decodeLesson(bytesOf(b64)) : null;
}
